#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
using Mat=array<array<ll,3>,3>;string s;vector<int>mate;bool compatible(int a,int b){return !a||!b||a!=b;}Mat solve(int l,int r){Mat result{};int p=mate[l];Mat first{};if(p==l+1){for(int a=0;a<3;a++)for(int b=0;b<3;b++)if((!a)!=(!b))first[a][b]=1;}else{auto inside=solve(l+1,p-1);for(int a=0;a<3;a++)for(int b=0;b<3;b++)if((!a)!=(!b))for(int x=0;x<3;x++)for(int y=0;y<3;y++)if(compatible(a,x)&&compatible(y,b))first[a][b]=(first[a][b]+inside[x][y])%1000000007;}if(p==r)return first;auto rest=solve(p+1,r);for(int a=0;a<3;a++)for(int b=0;b<3;b++)for(int x=0;x<3;x++)for(int y=0;y<3;y++)if(compatible(x,y))result[a][b]=(result[a][b]+first[a][x]*rest[y][b])%1000000007;return result;}int main(){cin>>s;mate.resize(s.size());vector<int>st;for(int i=0;i<(int)s.size();i++)if(s[i]=='(')st.push_back(i);else{mate[st.back()]=i;st.pop_back();}auto a=solve(0,s.size()-1);ll ans=0;for(auto&r:a)for(ll v:r)ans=(ans+v)%1000000007;cout<<ans<<'\n';}
